import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused ConvTranspose3d + Softmax + Sigmoid
fused_conv_softmax_sigmoid_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_conv_softmax_sigmoid_kernel(const float* input, float* output, int batch_size, int channels, int depth, int height, int width) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * channels * depth * height * width;

    if (idx < total_elements) {
        int b = idx / (channels * depth * height * width);
        int c = (idx / (depth * height * width)) % channels;
        int d = (idx / (height * width)) % depth;
        int h = (idx / width) % height;
        int w = idx % width;

        // Compute the softmax denominator
        float max_val = -INFINITY;
        for (int cc = 0; cc < channels; ++cc) {
            int input_idx = b * (channels * depth * height * width) + cc * (depth * height * width) + d * (height * width) + h * width + w;
            if (input[input_idx] > max_val) {
                max_val = input[input_idx];
            }
        }

        float sum_exp = 0.0f;
        for (int cc = 0; cc < channels; ++cc) {
            int input_idx = b * (channels * depth * height * width) + cc * (depth * height * width) + d * (height * width) + h * width + w;
            sum_exp += expf(input[input_idx] - max_val);
        }

        // Apply softmax and sigmoid
        int output_idx = b * (channels * depth * height * width) + c * (depth * height * width) + d * (height * width) + h * width + w;
        float softmax_val = expf(input[output_idx] - max_val) / sum_exp;
        output[output_idx] = 1.0f / (1.0f + expf(-softmax_val));
    }
}

torch::Tensor fused_conv_softmax_sigmoid_cuda(torch::Tensor input) {
    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto depth = input.size(2);
    auto height = input.size(3);
    auto width = input.size(4);
    auto output = torch::zeros_like(input);

    const int block_size = 256;
    const int num_blocks = (batch_size * channels * depth * height * width + block_size - 1) / block_size;

    fused_conv_softmax_sigmoid_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), batch_size, channels, depth, height, width);

    return output;
}
"""

fused_conv_softmax_sigmoid_cpp_source = (
    "torch::Tensor fused_conv_softmax_sigmoid_cuda(torch::Tensor input);"
)

# Compile the inline CUDA code for fused ConvTranspose3d + Softmax + Sigmoid
fused_conv_softmax_sigmoid = load_inline(
    name="fused_conv_softmax_sigmoid",
    cpp_sources=fused_conv_softmax_sigmoid_cpp_source,
    cuda_sources=fused_conv_softmax_sigmoid_source,
    functions=["fused_conv_softmax_sigmoid_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias=True):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, output_padding=output_padding, bias=bias)
        self.fused_conv_softmax_sigmoid = fused_conv_softmax_sigmoid

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.fused_conv_softmax_sigmoid.fused_conv_softmax_sigmoid_cuda(x)
        return x
